'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2);
const KEY='elabs-workspace-v1';let saveFailed=false;
const newOrg=name=>({id:uid(),name,answers:{},q:0,history:[],steps:[],systems:[],opportunities:[],missions:[],plan:[],processName:'',processOwner:'',roi:{employees:50,hours:6,cost:65,share:60,setup:5000,monthly:100,weeks:48}});
function fresh(){const o=newOrg('My organization');return {version:1,active:o.id,orgs:[o]};}
function validData(x){return x&&x.version===1&&Array.isArray(x.orgs)&&x.orgs.length>0&&x.orgs.length<=100&&x.orgs.every(o=>typeof o.id==='string'&&typeof o.name==='string'&&o.name.length<=120&&Number.isInteger(o.q)&&o.q>=0&&o.q<=23&&typeof o.processName==='string'&&typeof o.processOwner==='string'&&o.answers&&typeof o.answers==='object'&&!Array.isArray(o.answers)&&Object.entries(o.answers).every(([k,v])=>/^\d+$/.test(k)&&+k<24&&Number.isInteger(v)&&v>=1&&v<=5)&&['history','steps','systems','opportunities','missions','plan'].every(k=>Array.isArray(o[k]))&&o.history.every(h=>h&&typeof h.date==='string'&&Number.isFinite(h.total)&&h.total>=0&&h.total<=100&&Array.isArray(h.dims)&&h.dims.length===6&&h.dims.every(n=>Number.isFinite(n)&&n>=0&&n<=100))&&o.steps.every(s=>s&&typeof s.name==='string'&&typeof s.owner==='string'&&typeof s.system==='string'&&Number.isFinite(s.touch)&&s.touch>=0&&Number.isFinite(s.wait)&&s.wait>=0&&Number.isFinite(s.error)&&s.error>=0&&s.error<=100)&&o.systems.every(s=>s&&['name','purpose','owner','integration','quality','access'].every(k=>typeof s[k]==='string'))&&o.opportunities.every(p=>p&&typeof p.name==='string'&&['value','effort','risk','ready'].every(k=>Number.isFinite(p[k])&&p[k]>=1&&p[k]<=5))&&o.roi&&['employees','hours','cost','share','setup','monthly','weeks'].every(k=>Number.isFinite(o.roi[k])&&o.roi[k]>=0));}
let state;try{const x=JSON.parse(localStorage.getItem(KEY));state=validData(x)?x:fresh();}catch{state=fresh();saveFailed=true;}
function org(){return state.orgs.find(o=>o.id===state.active)||state.orgs[0];}function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;}catch{saveFailed=true;toast('Browser storage is unavailable or full. Export a backup to keep your work.');}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(rows){return rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');}
const dims=['Data','Process','People','Tooling','Governance','Ambition'];
const questions=[
['We know which system owns each critical business record.','Name the source of truth for customers, orders, employees and financial records.'],
['The data used by this workflow is accurate, complete and current.','Check a recent sample for missing values, duplicates and stale records.'],
['Authorized staff can access the required data in a usable format.','Consider export formats, access permissions and API availability.'],
['Data definitions and quality checks have a named owner.','A shared definition and an owner make quality issues actionable.'],
['The current process is documented from trigger to outcome.','Include exceptions, decisions and handoffs—not just the ideal path.'],
['Each step has an accountable owner and a clear completion rule.','A new team member should be able to identify who does what.'],
['We measure processing time, waiting time and rework.','Use observed baselines rather than assumptions wherever possible.'],
['The process is stable and unnecessary steps have been removed.','Standardize and simplify before adding automation.'],
['The team has the skills needed to operate and review the workflow.','Include process knowledge, tool literacy and output evaluation.'],
['People affected by the change have been involved in its design.','Ask frontline staff about exceptions and workarounds.'],
['There is capacity and a named owner for implementation.','The work has allocated time, not just general enthusiasm.'],
['Staff know how to escalate errors and use a manual fallback.','Practice a failure scenario and confirm the escalation route.'],
['The systems involved and their connections are documented.','Record data movement, ownership and duplicate entry.'],
['Required integrations are available and can be tested safely.','Check permissions, limits, supported APIs and test environments.'],
['Failures can be detected, logged and retried without duplicate actions.','Look for monitoring, idempotency and exception queues.'],
['We understand tool costs, vendor dependencies and exit options.','Include recurring fees, usage limits and data export.'],
['Data sensitivity and access permissions are defined for the workflow.','Identify personal, confidential and restricted data before any pilot.'],
['High-impact actions have a clear human approval policy.','Specify which actions pause and who may authorize them.'],
['Workflow decisions and changes can be reviewed in an audit trail.','Record inputs, outputs, approvals and important version changes.'],
['We have tested failure, privacy and output-quality scenarios.','Include incorrect inputs, model errors and an incident response.'],
['The automation supports a specific business outcome.','State the problem, intended beneficiary and measurable outcome.'],
['Success measures and a baseline are agreed before implementation.','Track quality and throughput alongside cost and time.'],
['Expected benefits and full delivery costs have been estimated.','Include implementation, oversight, maintenance and recurring fees.'],
['Leadership has agreed how to decide whether to scale the pilot.','Set the review date, owner and go/no-go criteria.']];
const advice=[['Establish the source of truth','Inventory critical records, assign data owners, and sample quality before connecting any automation.'],['Map and simplify the process','Capture triggers, owners, delays and exceptions. Remove unnecessary work and baseline cycle time.'],['Prepare the team','Name a delivery owner, involve the people doing the work, and rehearse escalation and fallback.'],['Connect systems deliberately','Document interfaces and access. Test failures, retries and duplicate handling before production.'],['Set the control boundaries','Classify sensitive data, assign approvers and test audit logging before high-impact actions.'],['Define the business case','Agree a measurable outcome, full costs and a pilot review date before scaling.']];
function scores(a=org().answers){if(Object.keys(a).length<24)return null;const ds=dims.map((_,i)=>Math.round(([0,1,2,3].reduce((s,j)=>s+a[i*4+j],0)/4-1)*25));return {dims:ds,total:Math.round(ds.reduce((s,x)=>s+x,0)/6)};}
const band=s=>s<40?'Foundation':s<60?'Developing':s<80?'Capable':'Advanced';
const link=(route,text,cls='button')=>`<a class="${cls}" href="#/${route}">${text}</a>`;
function head(k,t,d=''){return `<div class="page-head"><span class="eyebrow">${k}</span><h1>${t}</h1>${d?`<p>${d}</p>`:''}</div>`;}
const tools=[['assessment','◎','Readiness diagnostic','24 questions. Six dimensions. A clear starting point.','6–10 min','Baseline'],['process','⌘','Process mapper','Capture handoffs, reveal delays and remove friction.','Build a map','Process'],['systems','▦','Systems inventory','Understand your tools, data quality and integration gaps.','Map your stack','Systems'],['opportunities','◇','Opportunity matrix','Prioritize the right work before automating it.','Rank your ideas','Decisions'],['roi','↗','ROI calculator','Explore potential value and realistic payback.','Model a scenario','Value'],['workspace','◴','Progress & missions','Turn assessment findings into measurable improvement.','Keep improving','Progress']];
function toolCards(){return tools.map(([r,i,t,d,m,c])=>`<a href="#/${r}" class="card interactive"><div class="row"><span class="icon" aria-hidden="true">${i}</span><span class="eyebrow">${c}</span></div><h3>${t}</h3><p>${d}</p><div class="card-foot"><span>${m}</span><span>Open tool +</span></div></a>`).join('');}
function home(){const completed=org().history.length;return `<div class="wrap"><section class="hero"><div><span class="pill">THE FOUNDATION BEFORE AUTOMATION</span><h1>Better processes.<br>Smarter systems.<br><em>AI that delivers.</em></h1><p>Know what to improve before deciding what to automate. Your free workspace for organizational readiness, practical frameworks and governed AI.</p><div class="actions">${link('workspace',completed?'Continue your workspace':'Explore the assessment lab','button olive')}${link('canvas','Try the live canvas','button secondary')}</div><div class="hero-note">FREE TO EXPLORE &nbsp; / &nbsp; NO ACCOUNT REQUIRED &nbsp; / &nbsp; PROGRESS SAVED HERE</div></div><div class="hero-visual"><div class="visual-top"><span>YOUR NEXT OPERATING ADVANTAGE</span><span class="pill dark">Assessment lab</span></div><div class="orbit"><div class="ring"><strong>Assess</strong><small>then improve & automate</small></div><span class="orbit-chip a">⌘ &nbsp; Map the work</span><span class="orbit-chip b">◇ &nbsp; Find the opportunity</span></div><h3>Clarity before complexity.</h3><p>One connected journey from operational friction to a stronger automation foundation.</p><div class="signal-row"><a href="#/process"><b>01 · PROCESS</b>Find the friction</a><a href="#/systems"><b>02 · SYSTEMS</b>Connect the picture</a><a href="#/assessment"><b>03 · READINESS</b>Choose your next move</a></div></div></section><div class="strip"><span><b>06</b> practical assessment tools</span><span><b>04</b> practitioner frameworks</span><span><b>100%</b> browser-based workspace</span><span><b>$0</b> to get started</span></div><section class="section"><div class="section-head"><div><span class="eyebrow">THE ASSESSMENT LAB</span><h2>Make the invisible<br>work visible.</h2></div><p>Start with one process. See how people, systems and data fit together—then build your improvement plan.</p></div><div class="grid three">${toolCards()}</div></section><section class="dark-panel"><span class="eyebrow light">A MORE INTENTIONAL PATH</span><h2>Don’t just automate.<br>Build something worth scaling.</h2><div class="journey"><article><span class="num">01 / ASSESS</span><h3>Understand the reality</h3><p>Map processes and systems. Identify constraints and baseline performance.</p>${link('workspace','Start assessing','button lime')}</article><article><span class="num">02 / IMPROVE</span><h3>Strengthen the foundations</h3><p>Simplify the work, improve data quality and assign ownership. Track progress with missions.</p>${link('implementation','Build your plan','button lime')}</article><article><span class="num">03 / AUTOMATE</span><h3>Scale with control</h3><p>Prioritize a pilot, model its value and define human review before deployment.</p>${link('frameworks','Explore the frameworks','button lime')}</article></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">LEARN BY DOING</span><h2>Your next useful experiment.</h2></div></div><div class="grid two"><a class="card interactive" href="#/canvas"><span class="pill">INTERACTIVE SIMULATION</span><h3>The Governance Canvas</h3><p>Route a request, encounter an approval gate, and see what accountable automation looks like.</p><div class="card-foot">Run a safe simulation <span>+</span></div></a><a class="card interactive" href="#/prompts"><span class="pill">COPY & ADAPT</span><h3>Prompts with purpose</h3><p>Practical patterns for risk reviews, status updates, resource planning and operational decisions.</p><div class="card-foot">Explore the prompt library <span>+</span></div></a></div></section><div class="callout row"><div><span class="eyebrow">READY FOR IMPLEMENTATION?</span><h3>Free foundations. Production blueprints when you need them.</h3><p>Keep exploring for free, or choose a one-time kit from $97.</p></div>${link('pricing','Explore blueprints')}</div></div>`;}
function subnav(active){return `<div class="subnav" aria-label="Assessment tools">${[['workspace','Overview'],['assessment','Readiness'],['process','Process map'],['systems','Systems'],['opportunities','Opportunities'],['report','Report']].map(([r,t])=>link(r,t,r===active?'active':'')).join('')}</div>`;}
function selector(){return `<div class="workspace-select"><label for="org-select">Workspace</label><select id="org-select">${state.orgs.map(o=>`<option value="${esc(o.id)}" ${o.id===org().id?'selected':''}>${esc(o.name)}</option>`).join('')}</select><button class="button small secondary" data-action="new-org">New workspace</button><button class="text-button" data-action="rename-org">Rename</button></div>`;}
const missionDefs=[['baseline','Set your baseline','Complete the readiness diagnostic.',50],['map','Map the real work','Record at least three process steps.',40],['inventory','Know your stack','Inventory at least two systems.',40],['prioritize','Choose a pilot','Add an automation opportunity.',30],['owner','Align the owners','Confirm process and system ownership with the team.',20],['quality','Check the data','Review a sample of real records for quality gaps.',20],['review','Review the controls','Agree approval, escalation and manual fallback rules.',20],['remeasure','Measure the change','Complete a follow-up readiness assessment.',50]];
function earned(){const o=org();return missionDefs.filter(([id])=>({baseline:o.history.length>0,map:o.steps.length>=3,inventory:o.systems.length>=2,prioritize:o.opportunities.length>0,remeasure:o.history.length>=2}[id]??o.missions.includes(id)));}
function workspace(){const o=org(),s=o.history.at(-1),done=earned(),xp=done.reduce((a,x)=>a+x[3],0);return `<div class="wrap">${head('YOUR OPERATING WORKSPACE','Small steps. Stronger foundations.','Assess one workflow, act on what you find, and come back to see what changed.')}${selector()}${subnav('workspace')}<div class="grid four stats-grid"><div class="card"><span class="metric-label">Latest readiness</span><div class="stat">${s?s.total:'—'}<small> / 100</small></div><span class="muted">${s?band(s.total):'Set your first baseline'}</span></div><div class="card"><span class="metric-label">Process steps mapped</span><div class="stat">${o.steps.length}</div><span class="muted">${esc(o.processName||'Your process')}</span></div><div class="card"><span class="metric-label">Systems inventoried</span><div class="stat">${o.systems.length}</div><span class="muted">Make dependencies visible</span></div><div class="card"><span class="metric-label">Improvement XP</span><div class="stat">${xp}</div><span class="muted">${done.length} of 8 milestones</span></div></div><div class="dashboard-grid"><div class="card"><div class="row"><div><span class="eyebrow">YOUR NEXT MOVES</span><h3>Improvement missions</h3></div><span class="pill">${done.length}/8 complete</span></div><p>Earn progress for doing the work. XP tracks activity; readiness measures your self-assessed capabilities.</p>${missionDefs.map(([id,title,desc,points])=>{const yes=done.some(m=>m[0]===id),manual=['owner','quality','review'].includes(id);return `<div class="mission">${manual?`<input type="checkbox" data-mission="${id}" ${yes?'checked':''} aria-label="${title}">`:`<span style="flex:0 0 20px;color:var(--olive)" aria-label="${yes?'Complete':'Not complete'}">${yes?'✓':'○'}</span>`}<span><b>${title}</b><br><span class="muted">${desc}</span></span><small>+${points} XP</small></div>`}).join('')}<div class="actions">${link(o.history.length?'process':'assessment',o.history.length?'Continue mapping':'Set your baseline','button olive')}</div></div><div class="stack"><div class="dark-panel"><span class="eyebrow light">YOUR JOURNEY</span><h3>${xp>=200?'Foundation builder':xp>=100?'Systems explorer':'Curious operator'}</h3><p>${xp>=200?'Keep testing and remeasuring. Your next gains come from closing the gaps.':'Complete practical milestones to grow your operating capability.'}</p><div class="meter"><span style="width:${xp/270*100}%"></span></div><span class="muted">${xp} / 270 experience points</span></div><div class="card"><h3>Readiness over time</h3>${historyChart(o.history)}${o.history.length?link('assessment','Reassess readiness','button small secondary'):'<p class="muted">Your first completed assessment starts the trend.</p>'}</div><div class="card"><h3>Your progress belongs to you.</h3><p>Saved in this browser only. Download a backup to move devices or keep a durable copy.</p><div class="actions"><button class="button small" data-action="export">Export backup</button><button class="button small secondary" data-action="import">Import backup</button></div><p class="save-note">${saveFailed?'Storage unavailable: export before closing.':'No account or cloud sync. Clearing browser data removes local progress.'}</p></div></div></div><section class="section"><div class="section-head"><h2>Keep exploring.</h2></div><div class="grid three">${toolCards()}</div></section></div>`;}
function historyChart(h){return h.length?`<div class="history-bars">${h.slice(-6).map(x=>`<div class="history-col"><b>${x.total}</b><div class="bar" style="height:${x.total}%"></div><small>${new Date(x.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></div>`).join('')}</div><p class="save-note">Self-assessed readiness · last ${Math.min(h.length,6)} results</p>`:'<div class="empty">No completed assessments yet.</div>';}
function assessment(){const o=org(),i=Math.min(23,Math.max(0,o.q||0)),answered=Object.keys(o.answers).length;return `<div class="wrap">${head('BASELINE / READINESS DIAGNOSTIC','Where are you ready—and where aren’t you?','Rate your current practice, not your intention. Use 1 for absent and 5 for consistently measured and improved.')}${subnav('assessment')}<div class="row"><span class="muted">${esc(o.name)} · ${answered} of 24 answered</span><span class="pill">${Math.round(answered/24*100)}% complete</span></div><div class="meter"><span style="width:${answered/24*100}%"></span></div><div class="question-layout"><aside class="question-nav">${dims.map((d,j)=>`<button data-q="${j*4}" class="${Math.floor(i/4)===j?'active':''}">${String(j+1).padStart(2,'0')} · ${d} <small>(${[0,1,2,3].filter(k=>o.answers[j*4+k]).length}/4)</small></button>`).join('')}</aside><div><div class="card question"><div class="row"><span class="eyebrow">${dims[Math.floor(i/4)]}</span><span class="muted">Question ${i+1} / 24</span></div><h2>${questions[i][0]}</h2><p>${questions[i][1]}</p><div class="scale" role="group" aria-label="Readiness rating">${['Absent','Ad hoc','Defined','Consistent','Optimized'].map((t,j)=>`<button data-answer="${j+1}" aria-pressed="${o.answers[i]===j+1}" class="${o.answers[i]===j+1?'selected':''}"><strong>${j+1}</strong><span>${t}</span></button>`).join('')}</div><div class="row"><button class="button secondary" data-action="prev-q" ${i===0?'disabled':''}>Back</button><button class="button olive" data-action="next-q" ${!o.answers[i]?'disabled':''}>${i===23?'Finish assessment':'Next question'}</button></div></div><div class="q-mini" aria-label="Jump to question">${questions.map((_,j)=>`<button data-q="${j}" class="${o.answers[j]?'done':''}" aria-label="Question ${j+1}${o.answers[j]?', answered':''}" ${j===i?'aria-current="step"':''}>${j+1}</button>`).join('')}</div><p class="save-note">Answers save as you go. Use 1–5 to select a rating; Enter advances. ${link('methodology','How scoring works','link')}</p></div></div></div>`;}
function report(){const o=org(),s=o.history.at(-1);if(!s)return `<div class="wrap">${head('YOUR REPORT','Set a baseline first.','Complete the diagnostic to see your dimension scores, bottlenecks and recommended next steps.')}${subnav('report')}${link('assessment','Start the diagnostic')}</div>`;const bott=s.dims.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v).slice(0,3);const gate=s.dims[1]<60||s.dims[0]<60||s.dims[4]<60;return `<div class="wrap">${head('READINESS / EXECUTIVE SNAPSHOT',esc(o.name),'A practical self-assessment of your automation foundations.')}${subnav('report')}<div class="dark-panel report-top"><div class="score-circle"><b>${s.total}</b><span>OUT OF 100</span></div><div><span class="eyebrow light">${band(s.total)} · ${new Date(s.date).toLocaleDateString()}</span><h2>${gate?'Strengthen the foundations first.':'Prepare a controlled pilot.'}</h2><p>${gate?'Your process, data or governance score is below 60. Address these constraints before increasing automation scope.':'Use the process map and opportunity matrix to select a small pilot. Validate its safety and business value before scaling.'}</p></div></div><div class="actions no-print"><button class="button olive" data-action="print">Print / Save PDF</button><button class="button secondary" data-action="report-download">Download report</button>${link('assessment','Reassess','button secondary')}</div><div class="grid two"><div class="card"><h3>Six dimensions. One clear picture.</h3>${s.dims.map((v,i)=>`<div class="score-row"><span>${dims[i]}</span><div class="meter"><span style="width:${v}%"></span></div><b>${v}</b></div>`).join('')}</div><div class="card"><h3>Readiness history</h3>${historyChart(o.history)}<p class="muted">Compare assessments with the same scope and consistent evidence. Activity points never change your readiness score.</p></div></div><section class="section"><span class="eyebrow">PRIORITY FOUNDATIONS</span><h2>Your next three improvements.</h2><div class="grid three">${bott.map(({v,i},j)=>`<article class="card"><div class="row"><span class="pill">${dims[i]} · ${v}/100</span><span class="feature-number">0${j+1}</span></div><h3>${advice[i][0]}</h3><p>${advice[i][1]}</p>${link(['systems','process','implementation','systems','canvas','opportunities'][i],'Take action','button small secondary')}</article>`).join('')}</div></section><div class="grid two"><div class="card"><h3>Operational inventory</h3><p>${o.steps.length} process steps · ${o.systems.length} systems · ${o.opportunities.length} opportunities</p><p>${esc(o.processName||'Process not yet named')}. ${o.steps.length?`Total elapsed time: ${o.steps.reduce((a,x)=>a+x.touch+x.wait,0)} minutes per case.`:'Map a process to quantify delays and handoffs.'}</p></div><div class="card"><h3>Suggested sequence</h3><p><b>Days 1–30:</b> map, simplify and validate data.<br><b>Days 31–60:</b> run one controlled pilot.<br><b>Days 61–90:</b> measure outcomes and reassess.</p>${link('implementation','Open your plan','button small secondary')}</div></div><p class="report-note">This is a self-assessment, not a certification or an independently validated prediction. Scores guide investigation; estimates require measured baselines. No business outcome is guaranteed.</p></div>`;}
function processPage(){const o=org(),touch=o.steps.reduce((a,x)=>a+x.touch,0),wait=o.steps.reduce((a,x)=>a+x.wait,0),total=touch+wait,slow=[...o.steps].sort((a,b)=>b.wait-a.wait)[0];return `<div class="wrap">${head('ASSESSMENT LAB / PROCESS','See the work between the work.','Map one workflow from trigger to outcome. Capture touch time, waiting time and exceptions before choosing automation.')}${subnav('process')}<div class="grid four stats-grid">${[['Touch time',touch+' min'],['Waiting time',wait+' min'],['Elapsed time',total+' min'],['Touch-time ratio',total?Math.round(touch/total*100)+'%':'—']].map(([k,v])=>`<div class="card"><span class="metric-label">${k}</span><div class="stat" style="font-size:29px">${v}</div></div>`).join('')}</div><div class="grid two"><div class="card"><h3>Define the workflow</h3><label>Process name<input id="process-name" maxlength="120" value="${esc(o.processName)}" placeholder="e.g. Customer onboarding"></label><label>Accountable process owner<input id="process-owner" maxlength="120" value="${esc(o.processOwner)}" placeholder="Role or team"></label><p class="save-note">Saved automatically. Use role names rather than personal information.</p><form id="step-form"><h3>Add a process step</h3><div class="form-grid"><label class="full">Step name<input name="name" required maxlength="120" placeholder="e.g. Validate the request"></label><label>Owner / team<input name="owner" required maxlength="100"></label><label>System used<input name="system" maxlength="100" placeholder="e.g. CRM or spreadsheet"></label><label>Touch time (minutes)<input name="touch" type="number" min="0" max="100000" step="0.1" value="10" required></label><label>Wait time (minutes)<input name="wait" type="number" min="0" max="100000" step="0.1" value="0" required></label><label>Rework rate (%)<input name="error" type="number" min="0" max="100" step="0.1" value="0" required></label><label>Work type<select name="type"><option>Manual</option><option>Assisted</option><option>Automated</option><option>Decision / approval</option></select></label><label class="full">Exception / friction<textarea name="note" maxlength="500" placeholder="What makes this step slow or difficult?"></textarea></label></div><button class="button olive" style="margin-top:18px">Add step</button></form></div><div><div class="card"><div class="row"><h3>Current-state map</h3><button class="text-button" data-action="export-process">Export CSV</button></div>${o.steps.length?o.steps.map((s,i)=>`<article class="process-step"><div class="step-top"><span class="step-number">STEP ${i+1} · ${esc(s.type)}</span><div class="inline-actions"><button class="text-button" data-move="${i},-1" ${i===0?'disabled':''} aria-label="Move ${esc(s.name)} up">Up</button><button class="text-button" data-move="${i},1" ${i===o.steps.length-1?'disabled':''} aria-label="Move ${esc(s.name)} down">Down</button><button class="text-button" data-edit-step="${i}">Edit</button><button class="text-button" data-delete="steps,${i}">Remove</button></div></div><h3>${esc(s.name)}</h3><span class="muted">${esc(s.owner)} · ${esc(s.system||'No system recorded')}</span><p class="small-copy">${s.touch} min touch · ${s.wait} min wait · ${s.error}% rework</p>${s.note?`<p>${esc(s.note)}</p>`:''}</article>`).join(''):'<div class="empty">Add your first step. Start with the event that triggers the work.</div>'}</div>${slow?`<div class="callout"><span class="eyebrow">BOTTLENECK SIGNAL</span><h3>${slow.wait>0?esc(slow.name):'No waiting time recorded'}</h3><p>${slow.wait>0?`${slow.wait} minutes of waiting per case. Investigate the cause before deciding to automate.`:'Validate timings with real cases before drawing conclusions.'}</p><p class="small-copy">Elapsed time assumes sequential steps. Parallel work needs a separate critical-path analysis. Touch time is not necessarily value-added time.</p></div>`:''}</div></div>${o.steps.length?`<section class="section"><h2>Your workflow at a glance.</h2><div class="flow">${o.steps.map((s,i)=>`${i?'<span class="flow-sep" aria-hidden="true">→</span>':''}<div class="flow-node"><small>${String(i+1).padStart(2,'0')}</small>${esc(s.name)}<small>${esc(s.owner)} · ${s.touch+s.wait} min</small></div>`).join('')}</div></section>`:''}</div>`;}
function systemsPage(){const o=org(),gaps=o.systems.filter(s=>s.integration==='Manual / disconnected'||s.quality==='Unknown'||s.quality==='Needs cleanup');return `<div class="wrap">${head('ASSESSMENT LAB / SYSTEMS','Understand the stack behind the process.','Create a practical inventory of the systems, data and dependencies your workflow relies on.')}${subnav('systems')}<div class="grid two"><div class="card"><h3>Add a system</h3><form id="system-form"><div class="form-grid"><label>System name<input name="name" required maxlength="100" placeholder="e.g. Customer CRM"></label><label>Owner / team<input name="owner" required maxlength="100"></label><label class="full">Purpose / records held<input name="purpose" required maxlength="250" placeholder="e.g. Customer records and renewal dates"></label><label>Integration<select name="integration"><option>Manual / disconnected</option><option>File export / import</option><option>API / connector</option><option>Native integration</option></select></label><label>Data quality<select name="quality"><option>Unknown</option><option>Needs cleanup</option><option>Mostly reliable</option><option>Measured and reliable</option></select></label><label>Data sensitivity<select name="sensitivity"><option>Public</option><option>Internal</option><option>Confidential</option><option>Restricted / personal</option></select></label><label>Access controls<select name="access"><option>Not reviewed</option><option>Shared credentials</option><option>Role-based access</option><option>Role-based + audited</option></select></label></div><button class="button olive" style="margin-top:18px">Add system</button></form></div><div class="dark-panel"><span class="eyebrow light">FOUNDATION CHECK</span><h2>${o.systems.length} systems.<br>${gaps.length} to investigate.</h2><p>Investigate unknown data quality and disconnected systems before investing in automation.</p><div class="stack">${gaps.length?gaps.map(s=>`<div class="agent-node"><b>${esc(s.name)}</b><small>${esc(s.integration)} · ${esc(s.quality)}</small></div>`).join(''):'<p>Add systems to reveal integration and data-quality gaps.</p>'}</div><p class="save-note" style="color:#bdc8cb">Inventory observations, not a technical security audit.</p></div></div><section class="section"><div class="section-head"><h2>Your systems inventory.</h2><button class="button secondary" data-action="export-systems">Export CSV</button></div>${o.systems.length?`<div class="card table-scroll"><table><thead><tr><th>System & purpose</th><th>Owner</th><th>Integration</th><th>Data quality</th><th>Access</th><th>Actions</th></tr></thead><tbody>${o.systems.map((s,i)=>`<tr><td><b>${esc(s.name)}</b><br>${esc(s.purpose)}<br><small>${esc(s.sensitivity)}</small></td><td>${esc(s.owner)}</td><td>${esc(s.integration)}</td><td>${esc(s.quality)}</td><td>${esc(s.access)}</td><td><button class="text-button" data-edit-system="${i}">Edit</button> <button class="text-button" data-delete="systems,${i}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your inventory is empty. Add the systems used by your process.</div>'}</section></div>`;}
const priority=p=>Math.round((p.value*2+p.ready+(6-p.effort)+(6-p.risk))/25*100);
function opportunities(){const o=org();return `<div class="wrap">${head('ASSESSMENT LAB / OPPORTUNITIES','Automate the right work.','Balance business value with readiness, effort and risk. A high-value idea still needs safe, reliable foundations.')}${subnav('opportunities')}<div class="grid two"><div class="card"><h3>Evaluate an opportunity</h3><form id="opportunity-form"><label>Workflow / opportunity<input name="name" required maxlength="150" placeholder="e.g. Route incoming support requests"></label><div class="form-grid" style="margin-top:18px">${[['value','Business value','Low','High'],['ready','Foundation readiness','Weak','Strong'],['effort','Implementation effort','Low','High'],['risk','Business / data risk','Low','High']].map(([k,l,a,b])=>`<label>${l}<select name="${k}">${[1,2,3,4,5].map(v=>`<option value="${v}" ${v===3?'selected':''}>${v} · ${v===1?a:v===5?b:v===3?'Moderate':'Intermediate'}</option>`).join('')}</select></label>`).join('')}</div><button class="button olive" style="margin-top:18px">Add opportunity</button></form></div><div class="card"><span class="eyebrow">THE DECISION LENS</span><h3>Value is only half the question.</h3><div class="grid two"><div class="callout"><b>High value + ready</b><p>Consider a controlled pilot.</p></div><div class="callout"><b>High value + weak foundations</b><p>Improve the process and data first.</p></div></div><p>Priority = [2 × value + readiness + (6 − effort) + (6 − risk)] ÷ 25 × 100.</p><p class="small-copy">This is a transparent prioritization heuristic, not an ROI forecast. Risk 4–5 always calls for governance review; readiness 1–2 calls for foundation work.</p></div></div><section class="section"><h2>Your opportunity portfolio.</h2>${o.opportunities.length?`<div class="grid three">${o.opportunities.map((p,i)=>({...p,i})).sort((a,b)=>priority(b)-priority(a)).map(p=>`<div class="card"><span class="pill">${p.risk>=4?'Governance review':p.ready<=2?'Improve foundations':'Pilot candidate'}</span><h3>${esc(p.name)}</h3><div class="stat">${priority(p)}<small> priority / 100</small></div><p>Value ${p.value}/5 · Readiness ${p.ready}/5<br>Effort ${p.effort}/5 · Risk ${p.risk}/5</p><div class="actions">${link('roi','Model the value','button small secondary')}<button class="text-button" data-delete="opportunities,${p.i}">Remove</button></div></div>`).join('')}</div>`:'<div class="empty">Add an opportunity to start comparing your options.</div>'}</section></div>`;}
function roiResults(r){const weekly=r.employees*r.hours*r.share/100,gross=weekly*r.weeks*r.cost,net=gross-r.monthly*12;return {weekly,gross,net,payback:net>0?r.setup/(net/12):null,roi:r.setup>0?(net-r.setup)/r.setup*100:null};}
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function roi(){const r=org().roi;return `<div class="wrap">${head('VALUE / SCENARIO PLANNING','Model the value. See the assumptions.','Estimate capacity released by repetitive work, then account for implementation and recurring costs. Figures use USD.')}${subnav('roi')}<div class="grid two"><div class="card"><h3>Your operational scenario</h3><div class="stack">${[['employees','People involved',1,2000,1],['hours','Repetitive hours / person / week',0,40,.5],['cost','Loaded hourly cost ($)',0,250,5],['share','Potential time reduction (%)',0,100,5],['weeks','Working weeks / year',1,52,1],['setup','Implementation cost ($)',0,100000,500],['monthly','Recurring cost / month ($)',0,10000,50]].map(([k,t,min,max,step])=>`<label><span class="row">${t}<output id="out-${k}">${r[k]}</output></span><input type="range" data-roi="${k}" min="${min}" max="${max}" step="${step}" value="${r[k]}"></label>`).join('')}</div></div><div class="dark-panel"><span class="eyebrow light">MODELED ANNUAL CAPACITY VALUE</span><div id="roi-results"></div><p class="small-copy">Gross value = people × repetitive hours × reduction % × working weeks × hourly cost. Net annual value deducts recurring costs. Payback uses net monthly value and implementation cost.</p><p class="small-copy">Capacity value is not automatically cash savings. Real benefits depend on adoption, quality, oversight and how released time is used.</p><div class="actions"><button class="button lime" data-action="export-roi">Export scenario</button>${link('pricing','View blueprints','button secondary')}</div></div></div></div>`;}
function updateRoi(){const t=$('#roi-results');if(!t)return;const v=roiResults(org().roi);t.innerHTML=`<div class="stat" style="font-size:54px">${money(v.gross)}</div><p>${v.weekly.toFixed(1)} hours potentially released per week</p><div class="stack">${[['Net annual value',money(v.net)],['Implementation payback',v.payback===null?'No positive payback':v.payback===0?'No upfront cost':v.payback.toFixed(1)+' months'],['First-year ROI',v.roi===null?'Not defined with $0 setup':v.roi.toFixed(0)+'%']].map(([k,x])=>`<div class="agent-node"><small>${k}</small><h3>${x}</h3></div>`).join('')}</div>`;}
const frameworkData=[
['Strategy','Set your vision','Turn scattered AI experiments into an intentional program.',[
['North star','Write a one-sentence vision tied to a business outcome. Name the customer or team who benefits and how success will be measured.'],['Customer and operational signals','Interview the people doing the work. Capture recurring delays, errors and unmet needs before selecting tools.'],['Operating model','Name the executive sponsor, delivery owner, data owner and risk approver. Define who may approve, pause and audit the work.'],['AI champions','Recruit a small group of willing practitioners, allocate time and give them safe examples to test.'],['Personal transformation','Understand concerns about workload, skills and change. Plan training and feedback around real tasks.']]],
['Oversight','Keep control','Route tasks deliberately. Check outputs. Pause risky actions.',[
['Match the task to the model','Use lighter tools for routine classification and lookup. Reserve complex reasoning for tasks that need it, and evaluate quality on representative cases.'],['The four-step safety check','Request → AI prepares → risk check → approved action. Human approval is required where the consequences warrant it.'],['Design for failure','Expect lost context, malformed output, unavailable services and duplicate requests. Validate schemas, cap retries and preserve a manual fallback.'],['Make costs visible','Record usage, latency, quality and failures per workflow. Choose the model based on measured performance, not branding.'],['Five-week rollout','Week 1: classify tasks. Week 2: add logging. Week 3: test fallback paths. Week 4: connect the workflow. Week 5: review results and adjust.']]],
['Craft','Write better requests','Make the task, context and acceptance criteria explicit.',[
['Role · Task · Format','Use for a focused task: identify the expertise needed, the exact work and the desired output structure.'],['The full brief','For complex work, specify context, requirements, examples, constraints, output format and the acceptance check.'],['The measurable ask','Define a specific outcome, relevant constraints and a completion date. Make the result testable.'],['Test and compare','Try representative inputs and edge cases. Compare multiple outputs against a rubric; consistency alone does not establish correctness.'],['Before you use the output','Verify claims, protect confidential data, check for biased assumptions and record what a person reviewed.']]],
['People','Govern the work','Build ownership, capability and appropriate safeguards.',[
['Project governance','Create a steering group with a sponsor, delivery lead and security or risk representative. Keep a decision log and risk register.'],['Talent and culture','Assess skills, designate champions and create time for practice. Involve the team in changes to its own work.'],['Ethics and trust','Test representative cases for uneven outcomes. Explain how AI contributes and ensure meaningful review for consequential decisions.'],['Decision rights','Specify who approves, who can halt execution and who reviews incidents. Access should match responsibilities.'],['Review and improve','Measure quality, cost, time and incidents. Schedule a review of both the workflow and its control policies.']]]];
function frameworks(){return `<div class="wrap">${head('THE PRACTITIONER LIBRARY','Four frameworks. One operating discipline.','Use these alongside your assessments to turn insight into a practical, governed improvement plan.')}<div class="grid four">${frameworkData.map((f,i)=>`<a class="card interactive" href="#/framework-${i}"><span class="eyebrow">0${i+1} / ${f[0]}</span><h3>${f[1]}</h3><p>${f[2]}</p><span class="link">Explore framework</span></a>`).join('')}</div><section class="section"><div class="dark-panel"><span class="eyebrow light">START WITH REAL WORK</span><h2>Ground the framework<br>in your own process.</h2><p>A good strategy starts with the current state. Capture the process, systems and pain points before designing a future workflow.</p>${link('process','Map your first process','button lime')}</div></section>${link('prompts','Browse copy-and-adapt prompts','button olive')}</div>`;}
function framework(i){const f=frameworkData[i]||frameworkData[0];return `<div class="wrap article">${head('FRAMEWORK / '+f[0],f[1],f[2])}${link('frameworks','All frameworks','link')}<div class="section">${f[3].map(([h,p],j)=>`<details ${j===0?'open':''}><summary>${String(j+1).padStart(2,'0')} · ${h}</summary><p>${p}</p></details>`).join('')}</div><div class="callout"><h3>Put it into practice.</h3><p>${i===0?'Start with a named process and a measurable outcome.':i===1?'Try a risk gate in the simulated Governance Canvas.':i===2?'Choose a prompt and adapt it to a real task.':'Build these decisions into your implementation plan.'}</p>${link(['process','canvas','prompts','implementation'][i],'Open the next tool','button olive')}</div></div>`;}
