let sim={logs:[],pending:null,routed:0,approved:0,rejected:0,active:'',enabled:[true,true,true,true,true,true]};
const agents=[['Diagnostician','Readiness & operational signals'],['Architect','Workflow structure & specifications'],['Sanitizer','Data-handling review'],['Operator','Proposed workflow actions'],['Approval matrix','Risk-based decision gates'],['Audit trail','Session event log']];
function canvas(){return `<div class="wrap">${head('INTERACTIVE / GOVERNANCE CANVAS','Experience accountable automation.','A local simulation of request routing and approval gates. No AI model is called and no external action is executed.')}<div class="tabs">${[['Run my readiness diagnostic','Diagnostic'],['Draft a workflow specification','Architect'],['Send a customer email','High-risk action'],['Isolate production database server','Critical action'],['Generate a weekly audit brief','Audit trail']].map(([v,t])=>`<button data-sim-prompt="${v}">${t}</button>`).join('')}</div><div class="dark-panel canvas-layout"><div><span class="eyebrow light">THE AGENT MESH</span><h3>One request.<br>Visible controls.</h3><div class="agent-list">${agents.map(([n,d],i)=>`<div class="agent-node ${sim.active===n?'active':''}"><div class="row"><b>${n}</b><input type="checkbox" data-agent="${i}" ${sim.enabled[i]?'checked':''} ${i>=2?'disabled':''} aria-label="Enable ${n}"></div><small>${d}${i>=2?' · required in this demo':''}</small></div>`).join('')}</div></div><div><div class="row"><span class="pill dark">SIMULATION · ${sim.pending?'AWAITING REVIEW':'READY'}</span><button class="text-button" style="color:var(--lime)" data-action="reset-sim">Reset session</button></div><div class="console" style="margin-top:20px" role="log" aria-live="polite">${sim.logs.length?sim.logs.map(l=>`<p class="${l.type==='system'?'log':''}">${esc(l.text)}</p>`).join(''):'<p>SESSION READY<br>Choose a sample request or type your own.<br>Use fictional data only.</p>'}</div>${sim.pending?`<div class="approval"><b>${sim.pending.critical?'Critical action · authorized review required':'High-impact action · approval required'}</b><p>${esc(sim.pending.text)}</p><p class="small-copy">${sim.pending.critical?'This demo cannot perform identity verification or MFA. Review the escalation path; no execution is available.':'Approval only records a simulated decision. Nothing is sent or changed.'}</p>${sim.pending.critical?'<button class="button small" data-action="escalate-sim">Simulate escalation</button>':'<button class="button small olive" data-action="approve-sim">Approve simulation</button>'} <button class="button small secondary" style="color:var(--navy)" data-action="reject-sim">Reject</button></div>`:''}<form id="sim-form" class="canvas-input"><input aria-label="Simulation request" name="request" maxlength="500" placeholder="Describe a request…" required ${sim.pending?'disabled':''}><button class="button lime" ${sim.pending?'disabled':''}>Run simulation</button></form><div class="signal-row" style="margin-top:22px"><div class="agent-node"><b>${sim.routed}</b><small>Requests routed</small></div><div class="agent-node"><b>${sim.approved}</b><small>Approvals</small></div><div class="agent-node"><b>$0</b><small>API spend</small></div></div><button class="text-button" style="color:var(--lime);margin-top:20px" data-action="export-audit">Download session log</button></div></div><p class="save-note">Keyword routing demonstrates concepts only. It is not a security classifier, persistent audit ledger, or production approval system. Session resets when this page is reloaded.</p></div>`;}
function runSim(text){if(sim.pending)return toast('Resolve the current approval first.');sim.routed++;sim.logs.push({type:'user',text:'YOU · '+text});let agent='Architect',result='Prepared a workflow outline: trigger → input validation → processing → quality check → approval → logged output.';if(/isolate|production|delete|critical/i.test(text)){sim.pending={text,critical:true};agent='Approval matrix';result='CRITICAL · Execution halted. Escalate to the authorized owner for identity verification and policy review.';}else if(/send|email|block|publish|write|update|payment/i.test(text)){sim.pending={text,critical:false};agent='Approval matrix';result='HIGH IMPACT · A proposed external action requires human approval. Execution paused.';}else if(/diagnos|readiness|score/i.test(text)){agent='Diagnostician';const s=org().history.at(-1);result=s?`Latest local readiness: ${s.total}/100 (${band(s.total)}). Review low-scoring foundations before a pilot.`:'No local assessment is complete. Run the readiness diagnostic to establish a baseline.';}else if(/audit|brief|log/i.test(text)){agent='Audit trail';result=`Session summary: ${sim.routed} requests, ${sim.approved} simulated approvals, ${sim.rejected} rejections. No external actions executed.`;}if(!sim.enabled[agents.findIndex(a=>a[0]===agent)])result='This agent is disabled. Request held; no processing performed.';sim.active=agent;sim.logs.push({type:'system',text:agent.toUpperCase()+' · '+result});render(false);}
const phases=[['Days 1–30','Assess & simplify',['Complete the baseline diagnostic','Map the process, decisions and exceptions','Inventory systems and validate data quality','Assign process, data and approval owners','Remove redundant steps and record baseline metrics']],['Days 31–60','Pilot with controls',['Select one opportunity using the matrix','Agree success measures and acceptance criteria','Test representative inputs and failure scenarios','Add human review and a manual fallback','Measure time, quality and recurring cost']],['Days 61–90','Review & improve',['Compare results with the baseline','Review incidents, exceptions and adoption','Update operating procedures and training','Prepare an executive review and decision','Reassess readiness before expanding scope']]];
function implementation(){return `<div class="wrap">${head('YOUR PLAN / 30 · 60 · 90','Make improvement a repeatable practice.','A working checklist for moving from assessment to a measured, governed pilot. Check off actions as your team completes them.')}<div class="grid three">${phases.map(([tag,t,items],i)=>`<div class="card"><span class="eyebrow">${tag}</span><h3>${t}</h3>${items.map((v,j)=>`<label class="checkline"><input type="checkbox" data-plan="${i*5+j}" ${org().plan.includes(i*5+j)?'checked':''}><span>${v}</span></label>`).join('')}</div>`).join('')}</div><div class="callout row"><div><h3>${org().plan.length} of 15 actions complete.</h3><p>Validate one workflow fully before widening the scope.</p></div><button class="button olive" data-action="print">Print your plan</button></div></div>`;}
const resources=[['Tool','Readiness diagnostic','Establish your baseline across six dimensions.','assessment'],['Tool','Process mapper','Document steps, delays and exceptions.','process'],['Tool','Systems inventory','Capture ownership, quality and integration gaps.','systems'],['Tool','Opportunity matrix','Prioritize value, readiness, effort and risk.','opportunities'],['Tool','ROI calculator','Model value, recurring costs and payback.','roi'],['Guide','30 / 60 / 90 implementation plan','Turn findings into a practical sequence of actions.','implementation'],['Template','Executive brief','Use your current readiness results in a leadership memo.','brief'],['Guide','Transformation roadmap','Understand the journey from assessment to operation.','roadmap'],['Template','Prompt library','Copy and adapt operational request patterns.','prompts'],['Template','Shadow-AI inventory','Record tools, owners, data sensitivity and approvals.','download-shadow'],['Template','Vendor evaluation rubric','Compare data handling, integration, cost and exit options.','download-vendor'],['Guide','Scoring methodology','See exactly how the readiness score is calculated.','methodology']];
function resourcePage(){return `<div class="wrap">${head('THE OPERATOR’S LIBRARY','Useful tools. Practical next steps.','Find a template, explore a framework, or continue your assessment.')}<label class="resource-search">Find a resource<input id="resource-search" type="search" placeholder="Search by name or purpose"></label><div class="grid three" id="resource-grid">${resources.map(([tag,t,d,r])=>`<article class="card interactive" data-search="${(t+' '+d+' '+tag).toLowerCase()}"><span class="pill">${tag}</span><h3>${t}</h3><p>${d}</p>${r.startsWith('download-')?`<button class="button small secondary" data-action="${r}">Download CSV template</button>`:link(r,'Open resource','button small secondary')}</article>`).join('')}</div><p id="no-resources" hidden>No matching resources. Try a different keyword.</p></div>`;}
function methodology(){return `<div class="wrap article">${head('TRANSPARENT / METHODOLOGY','A score you can understand.','Six dimensions, 24 statements and a transparent calculation. Designed to guide investigation—not certify an organization.')}<div class="card"><h3>The rating scale</h3><p><b>1 · Absent:</b> no consistent practice.<br><b>2 · Ad hoc:</b> informal and variable.<br><b>3 · Defined:</b> documented but not consistently applied.<br><b>4 · Consistent:</b> routinely applied and monitored.<br><b>5 · Optimized:</b> measured and improved over time.</p><h3>The formula</h3><div class="prompt">Dimension = round((mean of its four answers − 1) ÷ 4 × 100)\nOverall = round(mean of the six dimension scores)</div><p class="save-note">All 24 answers are required. An all-1 assessment scores 0; an all-5 assessment scores 100. Every dimension has equal weight.</p></div><section class="section"><div class="grid two">${dims.map((d,i)=>`<div class="card"><span class="eyebrow">0${i+1}</span><h3>${d}</h3><p>${advice[i][1]}</p></div>`).join('')}</div></section><div class="card"><h3>Readiness bands</h3><p>0–39: Foundation · 40–59: Developing · 60–79: Capable · 80–100: Advanced.</p><p>If Data, Process or Governance scores below 60, the report recommends foundation work before expanding automation. A high overall score does not override a weak control area.</p><h3>What this score does—and doesn’t—mean</h3><p>This is an ELabs planning heuristic based on self-reported practice. It has not been presented as a validated industry benchmark. It does not establish security, legal compliance or guaranteed business value.</p><p>Use the same scope, respondent group and evidence standard for repeat assessments. Keep a record of observations supporting any score changes. XP and missions track participation independently of readiness.</p><h3>Migration note</h3><p>This GitHub Pages edition uses a newly written question bank because the original question data was not included in the source export. Its 0–100 normalization differs from the original page’s documented 20–100 formula. Treat the first assessment here as a new baseline.</p></div></div>`;}
function roadmap(){return `<div class="wrap">${head('THE TRANSFORMATION JOURNEY','Assess. Improve. Automate. Repeat.','Use the stage that matches your actual constraints. Governance begins before the pilot, not after it.')}<div class="stack">${[['01','Assess the current state','Map the work and systems. Complete the diagnostic and identify the weakest foundations.','workspace'],['02','Standardize and simplify','Clarify ownership, remove unnecessary steps and improve the underlying data.','process'],['03','Prepare a controlled pilot','Prioritize one opportunity and define risk controls, review criteria and a fallback.','opportunities'],['04','Implement and govern','Use the frameworks and blueprints to support delivery. Measure outcomes and exceptions.','pricing'],['05','Operate and improve','Review performance, retake the diagnostic and update your roadmap based on observed change.','implementation']].map(([n,t,d,r])=>`<div class="card row"><span class="feature-number">${n}</span><div style="flex:1"><h3>${t}</h3><p>${d}</p></div>${link(r,'Explore','button small secondary')}</div>`).join('')}</div></div>`;}
function brief(){const o=org(),s=o.history.at(-1),b=s?s.dims.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v).slice(0,3):[];return `<div class="wrap article">${head('FOR LEADERSHIP / EXECUTIVE BRIEF',esc(o.name),'A working brief based on the information saved in this browser.')}<div class="card"><span class="eyebrow">${new Date().toLocaleDateString()}</span><h3>The situation</h3><p>${s?`The latest self-assessment scores ${s.total}/100 (${band(s.total)}).`:'A readiness baseline has not yet been completed.'} The workspace includes ${o.steps.length} mapped process steps, ${o.systems.length} systems and ${o.opportunities.length} candidate opportunities.</p><h3>Priority constraints</h3><p>${b.length?b.map(x=>dims[x.i]+': '+x.v+'/100').join(' · '):'Complete the diagnostic and map one representative workflow to identify the constraints.'}</p><h3>Recommended decision</h3><p>Authorize a focused assessment and improvement cycle for ${esc(o.processName||'one clearly defined workflow')}. Assign an accountable owner, validate baseline quality and cycle time, and select a pilot only after its foundational gaps and controls are understood.</p><h3>Measures of success</h3><p>Track elapsed time, rework, output quality, adoption, operating cost and incidents. Use a defined review date to decide whether to adjust, stop or expand.</p><h3>Commercial options</h3><p>Free tools support assessment and planning. Optional one-time blueprints are available at $97, $149 and $297. Implementation and operating costs must be budgeted separately.</p></div><div class="actions"><button class="button olive" data-action="print">Print / Save PDF</button>${link('roi','Model the business case','button secondary')}</div></div>`;}
function partners(){return `<div class="wrap">${head('FOR CONSULTANTS / LOCAL CLIENT WORKSPACES','One method. Separate client workspaces.','Keep assessments and improvement plans separate by organization. All records remain in this browser; there is no shared team portal or billing system.')}<div class="actions"><button class="button olive" data-action="new-org">Add a client workspace</button><button class="button secondary" data-action="export">Export all workspaces</button></div><div class="grid three">${state.orgs.map(o=>{const s=o.history.at(-1);return `<article class="card"><span class="pill">${s?band(s.total):'Not assessed'}</span><h3>${esc(o.name)}</h3><div class="stat">${s?s.total:'—'}<small> / 100</small></div><p>${o.steps.length} process steps · ${o.systems.length} systems<br>${o.history.length} completed assessments</p><button class="button small secondary" data-open-org="${esc(o.id)}">Open workspace</button></article>`}).join('')}</div><div class="callout"><h3>Protect client confidentiality.</h3><p>Use organization aliases where practical. Exports contain all workspace records; share them only with intended recipients. Browser storage is not an access-controlled client database.</p></div></div>`;}
function cases(){return `<div class="wrap">${head('PATTERNS / CASE STUDIES','What improvement can look like.','Illustrative scenarios to help you recognize useful starting points. These are examples, not verified customer results.')}<div class="grid two">${[['B2B software','Customer support triage','Disconnected customer records and inconsistent routing.','Define categories, clean the source records and compare assisted triage with human-reviewed cases.','Routing accuracy, rework and time to assignment.'],['Financial services','Operational approvals','Unclear approval ownership and incomplete decision logs.','Define approval roles, risk thresholds and evidence requirements before automating routing.','Approval time, exception rate and audit completeness.'],['Health technology','Service operations','Process variation and incomplete handoff information.','Map the current state, minimize sensitive data and establish a reviewed handoff template.','Missing information, rework and service quality.'],['Logistics','Exception management','Manual status updates across multiple systems.','Inventory interfaces, define the source of truth and pilot a read-only exception dashboard.','Data freshness, time to resolution and duplicate entry.']].map(([i,t,b,a,m])=>`<article class="card"><span class="eyebrow">${i}</span><h3>${t}</h3><p><b>Constraint:</b> ${b}</p><p><b>Intervention:</b> ${a}</p><p><b>Measure:</b> ${m}</p></article>`).join('')}</div><div class="callout"><h3>Your baseline is the starting point.</h3>${link('workspace','Assess your own workflow','button olive')}</div></div>`;}
function faq(){const rows=[['What is free?','The assessment lab, local report, process mapper, systems inventory, opportunity matrix, ROI calculator, frameworks, prompt library, simulator and implementation checklist are free. Production blueprints remain paid products.'],['Where are my answers saved?','In local browser storage on this device and site address. Nothing entered into the assessment tools is sent to an AI service or ELabs server. Export a JSON backup before switching devices or clearing browser data.'],['Can I use the workspace on another device?','Yes. Export a backup, move that file securely, then import it on the other device. Imported workspaces are added as separate copies so they do not overwrite existing work. There is no automatic cloud synchronization.'],['How long does the diagnostic take?','Allow roughly 6–10 minutes for the 24 ratings if you know the process well. Gathering evidence and discussing the answers with a team will take longer.'],['Can I download a PDF?','Open the report or executive brief and select Print / Save PDF. Use your browser’s Save as PDF destination. A text report and structured JSON backup are also available.'],['Does the canvas run real AI or automation?','No. It is an explicitly labeled local simulation using keyword-based routing. It does not call models, send emails, change systems or perform real authentication.'],['How do purchases work?','The existing Stripe payment links open in a new tab. Product delivery is managed by the existing purchase service. This static site cannot validate payments, authenticate purchasers or securely deliver paid assets.'],['What happened to account login?','This edition intentionally uses browser-based workspaces rather than accounts. Login, password reset, OAuth consent and cloud account history require an external backend and are not presented as working features here.'],['Is the score an industry certification?','No. It is a transparent self-assessment heuristic. Validate findings with evidence and use qualified review where the stakes require it.'],['What third-party services load?','The page requests web fonts from Google Fonts; if unavailable, system fonts are used. Stripe is visited only when you choose a purchase link. There are no analytics scripts or AI API calls in this edition.'],['Can consultants use it with clients?','Yes. Create separate local workspaces from the Partner workspace page. Avoid sensitive personal data, and handle exported files according to your client obligations.']];return `<div class="wrap article">${head('HELP / PRIVACY','A few useful answers.','Understand the tools, the scores and where your information lives.')}${rows.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="callout"><h3>Need product support?</h3><a class="link" href="mailto:elefficiencylabs@gmail.com">elefficiencylabs@gmail.com</a></div></div>`;}
function route(){return (location.hash.slice(2)||'home').split('?')[0];}
const routes={home,workspace,assessment,report,'report-preview':report,process:processPage,systems:systemsPage,opportunities,roi,'roi-calculator':roi,frameworks,prompts:promptPage,pricing,canvas,resources:resourcePage,methodology,roadmap,'transformation-roadmap':roadmap,implementation,'implementation-guide':implementation,brief,'executive-brief':brief,partners,'partner-portal':partners,'case-studies':cases,faq};
function render(scroll=true){let r=route();const fn=routes[r]||(r.match(/^framework-[0-3]$/)?()=>framework(+r.at(-1)):r.match(/^tier-[1-3]$/)?()=>tierPage(+r.at(-1)-1):null);$('#main').innerHTML=fn?fn():`<div class="wrap">${head('PAGE NOT FOUND','Let’s get you back to useful work.')}${link('workspace','Open workspace')}</div>`;$('#main').classList.remove('fade');void $('#main').offsetWidth;$('#main').classList.add('fade');$$('header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#/'+r));document.title=(r==='home'?'Assess. Improve. Automate.':(r[0].toUpperCase()+r.slice(1).replaceAll('-',' ')))+' — Efficiency Labs';updateRoi();if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}if(saveFailed&&r==='workspace')toast('Export a backup: browser storage may be unavailable.');}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function orgDialog(rename=false){openModal(`<h2>${rename?'Rename workspace':'Create a workspace'}</h2><form id="org-form" data-rename="${rename}"><label>Organization or client alias<input name="name" required maxlength="120" value="${rename?esc(org().name):''}" autofocus></label><p class="save-note">Use an alias when working with confidential client information.</p><button class="button olive">${rename?'Save name':'Create workspace'}</button></form>`);}
function confirmDelete(collection,index){const item=org()[collection][index];if(!item)return;openModal(`<h2>Remove ${esc(item.name)}?</h2><p>This removes the entry from this local workspace. Export a backup first if you need to retain it.</p><button class="button danger" data-confirm-delete="${collection},${index}">Remove entry</button>`);}
function editItem(type,i){const o=org(),s=o[type][i];if(!s)return;const isStep=type==='steps';openModal(`<h2>Edit ${isStep?'process step':'system'}</h2><form id="edit-form" data-type="${type}" data-index="${i}"><div class="form-grid">${(isStep?['name','owner','system','touch','wait','error','note']:['name','owner','purpose']).map(k=>`<label>${({name:'Name',owner:'Owner / team',system:'System',touch:'Touch time (minutes)',wait:'Wait time (minutes)',error:'Rework (%)',note:'Exception / friction',purpose:'Purpose'})[k]}<input name="${k}" value="${esc(s[k])}" ${['touch','wait','error'].includes(k)?`type="number" min="0" max="${k==='error'?100:100000}" step="0.1"`:'maxlength="500"'} ${['name','owner','touch','wait','error','purpose'].includes(k)?'required':''}></label>`).join('')}${(isStep?[['type',['Manual','Assisted','Automated','Decision / approval']]]:[['integration',['Manual / disconnected','File export / import','API / connector','Native integration']],['quality',['Unknown','Needs cleanup','Mostly reliable','Measured and reliable']],['sensitivity',['Public','Internal','Confidential','Restricted / personal']],['access',['Not reviewed','Shared credentials','Role-based access','Role-based + audited']]]).map(([k,vs])=>`<label>${k[0].toUpperCase()+k.slice(1)}<select name="${k}">${vs.map(v=>`<option ${s[k]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}</div><button class="button olive">Save changes</button></form>`);}
function reportText(){const o=org(),s=o.history.at(-1);if(!s)return 'No assessment completed.';return `EFFICIENCY LABS — READINESS REPORT\n${o.name}\n${new Date(s.date).toLocaleString()}\n\nReadiness: ${s.total}/100 (${band(s.total)})\n${s.dims.map((v,i)=>dims[i]+': '+v+'/100').join('\n')}\n\nPRIORITY ACTIONS\n${s.dims.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v).slice(0,3).map(x=>advice[x.i].join(': ')).join('\n\n')}\n\nPROCESS: ${o.processName||'Not named'}\nOwner: ${o.processOwner||'Not recorded'}\nSteps: ${o.steps.length}\nSystems: ${o.systems.length}\nOpportunities: ${o.opportunities.length}\n\nThis is a self-assessment, not a certification. Validate findings with operational evidence.\nScoring: each dimension = round((mean rating - 1) / 4 * 100); total = mean of dimension scores.\n` ;}
const actions={
'new-org':()=>orgDialog(), 'rename-org':()=>orgDialog(true),
'export':()=>{download('efficiency-labs-backup.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Backup downloaded. It includes all local workspaces.');},
'import':()=>$('#import-file').click(),
'prev-q':()=>{org().q=Math.max(0,org().q-1);save();render(false);},
'next-q':()=>{const o=org();if(!o.answers[o.q||0])return;if(o.q<23){o.q++;save();render(false);}else{const s=scores();if(!s){o.q=questions.findIndex((_,i)=>!o.answers[i]);save();render(false);toast('Please complete the unanswered questions.');return;}const signature=JSON.stringify(o.answers);if(o.history.at(-1)?.signature===signature&&Date.now()-new Date(o.history.at(-1).date).getTime()<60000){location.hash='#/report';return;}o.history.push({...s,date:new Date().toISOString(),signature});save();location.hash='#/report';toast('Baseline saved. Your report is ready.');}},
'print':()=>window.print(), 'report-download':()=>download('efficiency-labs-readiness-report.txt',reportText()),
'export-process':()=>download('process-map.csv',csv([['Process','Process owner','Step','Name','Owner','System','Touch minutes','Wait minutes','Rework percent','Type','Friction'],...org().steps.map((s,i)=>[org().processName,org().processOwner,i+1,s.name,s.owner,s.system,s.touch,s.wait,s.error,s.type,s.note])]),'text/csv'),
'export-systems':()=>download('systems-inventory.csv',csv([['System','Owner','Purpose','Integration','Quality','Sensitivity','Access'],...org().systems.map(s=>[s.name,s.owner,s.purpose,s.integration,s.quality,s.sensitivity,s.access])]),'text/csv'),
'export-roi':()=>download('roi-scenario.json',JSON.stringify({assumptions:org().roi,results:roiResults(org().roi),currency:'USD',note:'Modeled capacity value, not guaranteed cash savings.'},null,2),'application/json'),
'download-shadow':()=>download('shadow-ai-inventory.csv',csv([['Tool','Purpose','Accountable owner','Users or roles','Data sensitivity','Approved use','Retention policy','Action required']]),'text/csv'),
'download-vendor':()=>download('vendor-evaluation-rubric.csv',csv([['Criterion','Score 1-5','Evidence','Open questions'],...['Data use and retention','Access control and auditability','Integration capability','Output quality and evaluation','Total operating cost','Resilience and incident response','Data export and exit plan'].map(x=>[x,'','',''])]),'text/csv'),
'reset-sim':()=>{sim={logs:[],pending:null,routed:0,approved:0,rejected:0,active:'',enabled:[true,true,true,true,true,true]};render(false);},
'approve-sim':()=>{if(!sim.pending||sim.pending.critical)return;sim.approved++;sim.logs.push({type:'system',text:'APPROVED · Simulated action completed. No external system was changed.'});sim.pending=null;render(false);},
'escalate-sim':()=>{if(!sim.pending?.critical)return;sim.logs.push({type:'system',text:'ESCALATED · Simulated referral to an authorized owner. Identity verification and execution are outside this demo.'});sim.pending=null;render(false);},
'reject-sim':()=>{if(!sim.pending)return;sim.rejected++;sim.logs.push({type:'system',text:'REJECTED · Proposed action cancelled.'});sim.pending=null;render(false);},
'export-audit':()=>download('governance-simulation-log.json',JSON.stringify({simulation:true,generatedAt:new Date().toISOString(),...sim},null,2),'application/json')};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.disabled)return;const o=org();if(b.dataset.action){actions[b.dataset.action]?.();return;}if(b.dataset.q!==undefined){o.q=+b.dataset.q;save();render(false);}if(b.dataset.answer){o.answers[o.q||0]=+b.dataset.answer;save();render(false);}if(b.dataset.move){const [i,d]=b.dataset.move.split(',').map(Number);if(o.steps[i]&&i+d>=0&&i+d<o.steps.length){[o.steps[i],o.steps[i+d]]=[o.steps[i+d],o.steps[i]];save();render(false);}}if(b.dataset.delete){const [c,i]=b.dataset.delete.split(',');confirmDelete(c,+i);}if(b.dataset.confirmDelete){const [c,i]=b.dataset.confirmDelete.split(',');o[c].splice(+i,1);save();$('#modal').close();render(false);toast('Entry removed.');}if(b.dataset.editStep!==undefined)editItem('steps',+b.dataset.editStep);if(b.dataset.editSystem!==undefined)editItem('systems',+b.dataset.editSystem);if(b.dataset.openOrg){state.active=b.dataset.openOrg;save();location.hash='#/workspace';}if(b.dataset.filter){promptFilter=b.dataset.filter;render(false);}if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(prompts[+b.dataset.copy][2]);toast('Prompt copied. Add your context before using it.');}catch{openModal(`<h3>Copy this prompt</h3><textarea readonly style="height:250px">${esc(prompts[+b.dataset.copy][2])}</textarea>`);$('#modal textarea').select();}}if(b.dataset.simPrompt)runSim(b.dataset.simPrompt);});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),o=org();if(form.id==='step-form'){for(const k of ['touch','wait','error'])d[k]=+d[k];o.steps.push(d);save();render(false);toast('Process step added.');}if(form.id==='system-form'){o.systems.push(d);save();render(false);toast('System added to your inventory.');}if(form.id==='opportunity-form'){for(const k of ['value','ready','effort','risk'])d[k]=+d[k];o.opportunities.push(d);save();render(false);toast('Opportunity added and ranked.');}if(form.id==='org-form'){const name=d.name.trim();if(!name)return;if(form.dataset.rename==='true')o.name=name;else{const n=newOrg(name);state.orgs.push(n);state.active=n.id;}save();$('#modal').close();if(route()!=='workspace')location.hash='#/workspace';else render(false);toast('Workspace saved.');}if(form.id==='edit-form'){if(form.dataset.type==='steps')for(const k of ['touch','wait','error'])d[k]=+d[k];Object.assign(o[form.dataset.type][+form.dataset.index],d);save();$('#modal').close();render(false);toast('Changes saved.');}if(form.id==='sim-form')runSim(d.request);});
document.addEventListener('input',e=>{const t=e.target,o=org();if(t.id==='process-name'){o.processName=t.value;save();}if(t.id==='process-owner'){o.processOwner=t.value;save();}if(t.dataset.roi){o.roi[t.dataset.roi]=+t.value;$('#out-'+t.dataset.roi).textContent=t.value;save();updateRoi();}if(t.id==='resource-search'){const q=t.value.toLowerCase();let count=0;$$('[data-search]').forEach(c=>{c.hidden=!c.dataset.search.includes(q);if(!c.hidden)count++;});$('#no-resources').hidden=count>0;}});
document.addEventListener('change',e=>{const t=e.target,o=org();if(t.id==='org-select'){state.active=t.value;save();render(false);}if(t.dataset.mission){o.missions=o.missions.filter(v=>v!==t.dataset.mission);if(t.checked)o.missions.push(t.dataset.mission);save();render(false);toast(t.checked?'Milestone recorded. +20 XP':'Milestone reopened.');}if(t.dataset.plan!==undefined){o.plan=o.plan.filter(v=>v!==+t.dataset.plan);if(t.checked)o.plan.push(+t.dataset.plan);save();render(false);}if(t.dataset.agent!==undefined)sim.enabled[+t.dataset.agent]=t.checked;});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw new Error('Backup is too large (maximum 5 MB).');const x=JSON.parse(await f.text());if(!validData(x))throw new Error('This is not a valid Efficiency Labs backup.');if(state.orgs.length+x.orgs.length>100)throw new Error('Maximum of 100 workspaces.');x.orgs.forEach(o=>{o.id=uid();o.name=o.name.slice(0,109)+' (imported)';state.orgs.push(o);});state.active=state.orgs.at(-1).id;save();location.hash='#/workspace';render(false);toast('Backup imported as separate workspaces. Existing work was preserved.');}catch(err){toast(err.message||'Unable to import this file.');}e.target.value='';});
document.addEventListener('keydown',e=>{if(route()!=='assessment'||$('#modal').open||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(/^[1-5]$/.test(e.key)){org().answers[org().q||0]=+e.key;save();render(false);}if(e.key==='Enter'){e.preventDefault();actions['next-q']();}});
$('#close-modal').onclick=()=>$('#modal').close();$('.menu').onclick=()=>{const open=$('header').classList.toggle('open');$('.menu').setAttribute('aria-expanded',open);};
window.addEventListener('hashchange',()=>{$('header').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');render();});
render(false);
